<?php
require_once __DIR__ . '/../db.php'; admin_required(); $pdo=db(); $error=''; $message='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try {
    $action=$_POST['action']??'save'; $id=(int)($_POST['id']??0);
    if ($action==='delete') {
        $stmt=$pdo->prepare('SELECT cover_path FROM room_categories WHERE id=?');$stmt->execute([$id]);$paths=array_filter([$stmt->fetchColumn()?:null]);
        $stmt=$pdo->prepare('SELECT id FROM rooms WHERE category_id=?');$stmt->execute([$id]);foreach($stmt->fetchAll(PDO::FETCH_COLUMN) as $roomId)$paths=array_merge($paths,room_image_paths($pdo,(int)$roomId));
        $pdo->prepare('DELETE FROM room_categories WHERE id=?')->execute([$id]);foreach(array_unique($paths) as $path)delete_uploaded_image($path);$message='Category, its rooms, and their images deleted.';
    } else {
        $title=trim($_POST['title']??'');$slug=strtolower(trim($_POST['slug']??''));if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$title)?:$title),'-'));
        $location=trim($_POST['location']??'');$priceFrom=(float)($_POST['price_from']??0);$priceTo=trim($_POST['price_to']??'');
        if($title===''||$slug===''||$location===''||$priceFrom<=0)throw new RuntimeException('Title, URL slug, location, and starting price are required.');
        if(!preg_match('/^[a-z0-9-]+$/',$slug))throw new RuntimeException('Use lowercase letters, numbers, and hyphens in the URL slug.');
        $description=trim($_POST['description']??'');$featured=isset($_POST['is_featured'])?1:0;$sort=(int)($_POST['sort_order']??0);$oldCover=null;
        if($id){$stmt=$pdo->prepare('SELECT cover_path FROM room_categories WHERE id=?');$stmt->execute([$id]);$oldCover=$stmt->fetchColumn()?:null;$pdo->prepare('UPDATE room_categories SET title=?,slug=?,description=?,location=?,cover_path=NULL,price_from=?,price_to=?,is_featured=?,sort_order=? WHERE id=?')->execute([$title,$slug,$description,$location,$priceFrom,$priceTo!==''?(float)$priceTo:null,$featured,$sort,$id]);}
        else $pdo->prepare('INSERT INTO room_categories(title,slug,description,location,cover_path,price_from,price_to,is_featured,sort_order) VALUES(?,?,?,?,NULL,?,?,?,?)')->execute([$title,$slug,$description,$location,$priceFrom,$priceTo!==''?(float)$priceTo:null,$featured,$sort]);
        if($oldCover)delete_uploaded_image($oldCover);$message='Room category saved. Its homepage cover is generated from its text details.';
    }
} catch(Throwable $e) { $error=$e instanceof PDOException?'Could not save category. Check that its URL slug is unique.':$e->getMessage(); } }
$edit=null;if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM room_categories WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch(PDO::FETCH_ASSOC)?:null;}
$cats=$pdo->query('SELECT c.*,COUNT(r.id) AS room_count FROM room_categories c LEFT JOIN rooms r ON r.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.id')->fetchAll(PDO::FETCH_ASSOC);admin_header('Room categories');
if($message):?><div class="admin-alert ok"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="admin-alert"><?=e($error)?></div><?php endif;?>
<section class="admin-card"><h2><?=$edit?'Edit':'Create'?> homepage category</h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="admin-form-grid"><label>Category title<input required name="title" value="<?=e($edit['title']??'')?>" placeholder="Deluxe Sea View"></label><label>URL slug<input name="slug" value="<?=e($edit['slug']??'')?>" placeholder="deluxe-sea-view"></label><label>Location<input required name="location" value="<?=e($edit['location']??'')?>" placeholder="Kolatoli Beach, Cox’s Bazar"></label><label>Starting price (৳)<input required type="number" min="1" step="1" name="price_from" value="<?=e($edit['price_from']??'')?>"></label><label>Highest price (৳), optional<input type="number" min="1" step="1" name="price_to" value="<?=e($edit['price_to']??'')?>"></label><label>Order on homepage<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label class="full">Homepage cover preview<div class="category-text-preview"><span>ROOM CATEGORY</span><b><?=e($edit['title']??'Your category title')?></b><small><?=e($edit['location']??'Cox’s Bazar')?> · from ৳ <?=e(number_format((float)($edit['price_from']??0)))?></small></div></label><label class="full">Short description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label class="check-line"><input type="checkbox" name="is_featured" <?=!isset($edit['is_featured'])||$edit['is_featured']?'checked':''?>>Show on homepage</label></div><p><button class="admin-button">Save category</button></p></form></section>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Homepage cover</th><th>Category</th><th>Location</th><th>Price</th><th>Rooms</th><th>Actions</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><div class="category-text-preview category-text-preview-small"><span>ROOM CATEGORY</span><b><?=e($c['title'])?></b></div></td><td><?=e($c['title'])?></td><td><?=e($c['location'])?></td><td>৳ <?=e(number_format((float)$c['price_from']))?><?= $c['price_to']?' – ৳ '.e(number_format((float)$c['price_to'])):''?></td><td><?=e($c['room_count'])?></td><td><div class="admin-actions"><a class="admin-button" href="?edit=<?=$c['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this category, all its rooms, and all their images?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="admin-button danger">Delete</button></form></div></td></tr><?php endforeach;?><?php if(!$cats):?><tr><td colspan="6">No room categories yet.</td></tr><?php endif;?></tbody></table></div><?php admin_footer();
